<template data-option-template><div class="variant-option-row"><div class="form-grid"><label>Option name<input data-option-label maxlength="60" required></label><label class="check"><input type="checkbox" data-option-active checked>Available</label><div data-color-fields><label>Swatch HEX (optional)<input data-option-swatch maxlength="7" placeholder="#1A1A1A" pattern="#[A-Fa-f0-9]{6}"></label><label>Color image URLs (one per line)<textarea data-option-images rows="2"></textarea></label><label>Upload images for this color<input type="file" data-option-upload multiple accept="image/jpeg,image/png,image/webp"></label><small>JPG, PNG or WebP, up to 4 MB per file.</small><div class="variant-image-previews" data-option-previews></div></div></div><div class="form-actions"><button type="button" class="text-button" data-option-up>Move up</button><button type="button" class="text-button" data-option-down>Move down</button><button type="button" class="text-button danger" data-option-remove>Remove option</button></div></div></template>
<template data-combination-template><div class="variant-combination"><div class="form-grid"><label data-size-cell>Size<select data-combination-size required></select></label><label data-color-cell>Color<select data-combination-color required></select></label><label>SKU (optional)<input data-combination-sku maxlength="80"></label><label>Price override (optional)<input data-combination-price type="number" min="0" step="0.01" placeholder="Use product price"></label><label>Stock quantity<input data-combination-stock type="number" min="0" max="1000000" value="0" required></label><label class="check"><input data-combination-active type="checkbox" checked>Available</label></div><p class="muted" data-combination-used hidden>Used by existing orders. Removal archives this configuration and keeps the saved selections.</p><button class="text-button danger" type="button" data-combination-remove>Remove combination</button></div></template>
